gPH(){return"\u0938\u092e\u092f \u0915\u0947 \u0938\u093e\u0925 \u0926\u0930\u0947\u0902 \u0932\u0949\u0917 \u0915\u0930\u0947\u0902 \u2014 \u0935\u093f\u0926\u0947\u0936\u0940 \u092e\u0941\u0926\u094d\u0930\u093e \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c\u094b\u0902 \u0915\u094b \u0938\u094d\u0935\u0924\u0903 \u092d\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u092a\u0941\u0928\u0930\u094d\u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0924\u093e \u0939\u0948"},
gPR(){return"\u0924\u0930\u093e\u091c\u093c\u0942 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0928\u0915\u0926, \u0907\u0915\u094d\u0935\u093f\u091f\u0940, \u0914\u0930 \u0905\u0928\u094d\u092f \u0916\u093e\u0924\u0947 \u0915\u0939\u093e\u0902 \u0925\u0947"},
gPB(){return"\u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932"},
